\label{thm:odd-cayley-graphs}
	Let $G$ be the Cayley graph of an abelian group with $n:=|G|\geq 3$ odd.
	Then~$G \in \mathcal{H}$ if and only if~$G \in \{K_n, C_n\}$.

\label{thm:cart-prod}
	Let \(G\) and \(H\) be Hamiltonian graphs.
	\begin{itemize}
		\item If \(G\) and \(H\) are relatively prime, then \(G \operatorname{\square} H \notin \mathcal{H}\).
		\item If \(G\) is prime, then \(G^{\operatorname{\square} n} \in \mathcal{H}\) if and only if $n=1$ and $G\in \mathcal{H}$.
	\end{itemize}

\label{lem:cartesian-K2_odd_noncycle}
	Let $G$ be Hamiltonian with $|G|=:k$ odd and $G\neq C_k$. 
	Then $G \operatorname{\square} K_2 \notin \mathcal{H}$.

\label{lemma:divisibilitylemma}                    
	Let $G \in \mathcal{H}$ and assume that $G = \operatorname{Cay}(\Gamma, S)$ for an abelian group $\Gamma$ and a generating set $S$.
	\begin{enumerate}
		\item Suppose that $|\Gamma|$ is odd. If $S$ contains an element of order $pm$ for a prime $p$ and $m > 1$, then~$p$ divides $\kappa(G)$.
		\item If $|\Gamma|$ is even, then $\kappa(G)$ is even.
	\end{enumerate}

\label{lemma:small-groups}
	Let $G$ be the Cayley graph of an abelian group \(\Gamma\).
	\begin{itemize}
		\item Assume that $n:=|\Gamma|\leq 16$. Then $G \in \mathcal{H}$ if and only if one of the following holds
		\begin{itemize}
			\item $G \in \{K_n, C_n, C_4 \operatorname{\square} K_2\}$,
			\item $G=K_{k,k}$ where $k=n/2$,
			\item $G=C_k \operatorname{\square} K_2$ where $k=n/2$ is odd.
		\end{itemize}
		\item Assume that \(\Gamma \in \{\mathbb{Z}_3 \times \mathbb{Z}_3 \times \mathbb{Z}_3, \mathbb{Z}_9 \times \mathbb{Z}_3\}\). Then \(G \in \mathcal{H}\) if and only if \(G = K_{27}\).
	\end{itemize}

\label{thm:cyclic_generator}
	Let~\(\Gamma \cong \mathbb{Z}_n\) and~\(S\) be a generating set of~\(\Gamma\) containing an element of order~\(n\). Let~\(G = \operatorname{Cay}(\Gamma,S)\). Then, the following are equivalent:
	\begin{enumerate}
		\item $ G \in \mathcal{H}$, \label{item:cyclic_gen_graph_in_H}
		\item every Hamiltonian cycle~$C$ in~$G$ has Hamilton compression~$\kappa(C)=n$,  \label{item:cyclic_gen_rotation_one}
		\item we have $G \in \{K_n, C_n\}$ or $n=2m$ is even and $G=K_{m,m}$.\label{item:cyclic_gen_list_of_graphs_in_H}
	\end{enumerate}

\label{def:layer-structure}
	Let $G$ be a graph and $l \in \mathbb{N}_{\geq 1}$.
	If there is a decomposition $V(G) = V_1 \operatorname{\dot{\cup}} \dots \operatorname{\dot{\cup}} V_l$ such that
	\begin{enumerate}
		\item for $i \in \{1, \dots, l-1\}$, $G$ contains a perfect matching between $V_i$ and $V_{i+1}$ that defines an isomorphism between $G[V_i]$ and $G[V_{i+1}]$, and
		\item the graph $K:= G[V_1] \cong \dots \cong G[V_l]$ is Hamiltonian,
	\end{enumerate}
	we say that~$G$ has~\emph{$K$-$l$-layer structure}.
	In this case, we call $G[V_1], \dots ,G[V_l]$ the \emph{layers} of~$G$.

\label{lem:zigzag_mu}
	Let $G$ be a graph with $K$-$l$-layer structure, where $l\geq 5$ is odd, let $k:=|K|$, and let $C$ be the $C_K$-$\ensuremath{\boldsymbol{a}}$-zigzag cycle for some choice of $C_K$ and $\ensuremath{\boldsymbol{a}}$. Then we have
	\begin{equation*}
		\mu(C)=2k-1+2\sum_{i=1}^{(l-3)/2} (a_i+1).
	\end{equation*}

	In particular, we obtain that $\mu(C)$ is odd. 
	Even further, for any odd number $\mu^*\in \mathbb{N}$ with~$2k-1+(l-3)\leq \mu^* \leq 2k-1+(l-3)(k-1)$, there is a choice for $\ensuremath{\boldsymbol{a}}$ such that the~$C_K$-$\ensuremath{\boldsymbol{a}}$-zigzag cycle $C$ fulfills~$\mu(C)=\mu^*$.

\label{thm:layerstructure}
	Let $G \in \mathcal{H}$ be a graph of odd order that has $K$-$l$-layer structure and let~$k:=|K|$.
	Assume that one of the following conditions holds
	\begin{enumerate}
		\item $k,l\geq 7$ and $\kappa(G)\geq 5$
		\item $k,l \geq 5$ and, for every prime $p$ with $p|n:=|G|$, we have $p|\kappa(G)$.
	\end{enumerate}
	Then~$K$ is isomorphic to $C_k$ or $K_k$.

\label{lemma:cayleycycle}
Let $\Gamma$ be an abelian group of odd order with generating set $S$. 
Suppose that the Cayley graph $G = \operatorname{Cay}(\Gamma,S)$ is Hamiltonian-transitive and  $\kappa(G) > 1$. Assume that $G$ has a group-induced $K$-$l$-layer structure with $k\coloneqq|K|\geq 5$ and $l\geq5$. Then we have $K \not \cong C_k$.
